package com.singtel.redemptionservice;import jakarta.persistence.*;import java.util.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="redemptions",uniqueConstraints=@UniqueConstraint(name="redemption_idempotency",columnNames={"actor","idempotencyKey"}),indexes={@Index(name="redemption_customer_promotion",columnList="customerId,promotionId,status"),@Index(name="redemption_date",columnList="redeemedAt")})public class Redemption{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID promotionId;@Column(nullable=false)public String customerId;@Column(nullable=false,length=128)public String idempotencyKey;@Column(nullable=false)public String actor;@Column(nullable=false)public String status="REDEEMED";@Column(nullable=false,precision=19,scale=2)public BigDecimal discountAmount;@Column(nullable=false,length=3)public String currency;@Column(nullable=false)public Instant redeemedAt=Instant.now();public String correlationId;public Instant cancelledAt;public Redemption(){}}